source='''def transform(grid):
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    markers = {value for value in counts if value != background}
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            value = row[c - 1]
            if value in markers and row[c + 1] == value and row[c] == background:
                out[r][c] = 2
    return out
